export const icons={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',folder:'M3 6h7l2 2h9v12H3Z',save:'M4 3h14l3 3v15H3V3h1m3 0v7h10V3M7 21v-7h10v7',undo:'M8 5 3 10l5 5M3 10h11a6 6 0 0 1 0 12',redo:'m16 5 5 5-5 5m5-5H10a6 6 0 0 0 0 12',play:'m7 3 14 9-14 9Z',stop:'M5 5h14v14H5Z',settings:'M9 3h6l1 4 4 1v8l-4 1-1 4H9l-1-4-4-1V8l4-1ZM12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',cloud:'M7 18H5a4 4 0 0 1-1-8 7 7 0 0 1 13-3 5 5 0 0 1 2 11h-2m-5-8v11m-4-4 4 4 4-4',cursor:'m5 3 14 9-7 1-3 7Z',hand:'M6 11V7a2 2 0 0 1 4 0v5-7a2 2 0 0 1 4 0v7-5a2 2 0 0 1 4 0v6-3a2 2 0 0 1 4 0v5c0 6-3 8-8 8-3 0-4-2-6-4l-4-5a2 2 0 0 1 2-3Z',move:'M12 2v20M2 12h20M8 6l4-4 4 4M8 18l4 4 4-4M6 8l-4 4 4 4m12-8 4 4-4 4',box:'M3 3h6m6 0h6v6m0 6v6h-6m-6 0H3v-6m0-6V3',grid:'M3 3h18v18H3ZM9 3v18m6-18v18M3 9h18M3 15h18',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',cube:'m12 2 10 5v10l-10 5-10-5V7Zm0 10v10M2 7l10 5 10-5',bolt:'m13 2-9 12h7l-1 8L21 9h-8Z',menu:'M3 6h18M3 12h18M3 18h18',plus:'M12 4v16M4 12h16',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 6 6',layers:'m12 2 10 5-10 5L2 7Zm-10 9 10 5 10-5m-20 6 10 5 10-5',code:'m8 6-6 6 6 6m8-12 6 6-6 6',check:'m4 12 5 5L20 6',x:'m5 5 14 14M5 19 19 5',volume:'M3 9h5l5-5v16l-5-5H3Zm14-3a8 8 0 0 1 0 12',fit:'M3 9V3h6m6 0h6v6m0 6v6h-6M9 21H3v-6',duplicate:'M8 8h13v13H8ZM3 16V3h13',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7Zm10-3a3 3 0 1 0 0 6 3 3 0 0 0 0-6'};
export const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.box}"/></svg>`;
const importedImages=new Map();
export function paintObject(ctx,o){
 if(o.asset&&/^data:image\/(png|jpeg|webp|gif);base64,/.test(o.asset)){let image=importedImages.get(o.asset);if(!image){image=new Image();image.onload=()=>window.dispatchEvent(new Event('playform-asset-ready'));image.src=o.asset;importedImages.set(o.asset,image)}if(image.complete&&image.naturalWidth){ctx.drawImage(image,o.x,o.y,o.w,o.h);return}}
 const{x,y,w,h,type}=o;ctx.save();ctx.translate(x,y);ctx.fillStyle=o.color;ctx.strokeStyle='#182333';ctx.lineWidth=3;
 if(type==='platform'){
  ctx.fillStyle='#604034';ctx.fillRect(0,0,w,h);ctx.save();ctx.beginPath();ctx.rect(0,0,w,h);ctx.clip();for(let row=0;row<Math.min(h/24,80);row++)for(let col=0;col<Math.min(w/24,80);col++){ctx.fillStyle=['#754b39','#684131','#83533b','#5c3b37'][(row*7+col*3)%4];ctx.fillRect(col*24+2,row*24+2,21,21);ctx.fillStyle='#9b6542';ctx.fillRect(col*24+3,row*24+4,8,4)}ctx.restore();ctx.fillStyle='#355a1c';ctx.fillRect(0,0,w,16);ctx.fillStyle=o.color;ctx.fillRect(0,0,w,10);for(let i=0;i<Math.min(w,2000);i+=16){ctx.fillStyle='#a5e742';ctx.fillRect(i,0,12,4);ctx.fillStyle=o.color;ctx.fillRect(i+4,8,8,8)}ctx.strokeStyle='#283325';ctx.strokeRect(0,0,w,h);
 }else if(type==='coin'){
  ctx.fillStyle='#e7950a';ctx.beginPath();ctx.ellipse(w/2,h/2,w/2,h/2,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle=o.color;ctx.beginPath();ctx.ellipse(w/2,h/2,w*.36,h*.38,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#fff48d';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#fff28b';ctx.fillRect(w*.39,h*.23,w*.15,h*.52);
 }else if(type==='hazard'){
  const count=Math.max(1,Math.floor(w/28)),step=w/count;for(let i=0;i<count;i++){ctx.fillStyle='#dce8ef';ctx.beginPath();ctx.moveTo(i*step,h);ctx.lineTo(i*step+step/2,0);ctx.lineTo((i+1)*step,h);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#9caebb';ctx.beginPath();ctx.moveTo(i*step+step/2,3);ctx.lineTo((i+1)*step-2,h-2);ctx.lineTo(i*step+step*.6,h-2);ctx.fill()}
 }else if(type==='flag'){
  ctx.fillStyle='#6b4733';ctx.fillRect(2,h-6,w*.7,6);ctx.fillStyle='#dbb475';ctx.fillRect(8,0,5,h-4);ctx.strokeRect(8,0,5,h-4);ctx.fillStyle='#ef454f';ctx.beginPath();ctx.moveTo(14,4);ctx.lineTo(w-2,16);ctx.lineTo(14,32);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#f9ce61';ctx.fillRect(8,-3,6,6);
 }else if(type==='player'||type==='enemy'){
  ctx.fillStyle=type==='enemy'?'#ec5268':o.color;ctx.beginPath();ctx.roundRect(0,0,w,h,5);ctx.fill();ctx.stroke();ctx.fillStyle=type==='enemy'?'#ff8c95':'#f1f9ff';ctx.fillRect(4,4,w-8,6);ctx.fillStyle=type==='enemy'?'#a72448':'#7d9ab4';ctx.fillRect(4,h-7,w-8,4);ctx.fillStyle='#1a263a';ctx.fillRect(w*.23,h*.37,5,9);ctx.fillRect(w*.64,h*.37,5,9);ctx.fillRect(w*.45,h*.7,5,3);if(type==='enemy'){ctx.strokeStyle='#1a263a';ctx.beginPath();ctx.moveTo(6,10);ctx.lineTo(14,15);ctx.moveTo(w-6,10);ctx.lineTo(w-14,15);ctx.stroke()}
 }else if(type==='camera'){
  ctx.fillStyle='#8490a1';ctx.fillRect(0,h*.2,w,h*.7);ctx.strokeRect(0,h*.2,w,h*.7);ctx.fillStyle='#344053';ctx.beginPath();ctx.arc(w/2,h*.55,h*.25,0,Math.PI*2);ctx.fill();ctx.stroke();
 }else{ctx.fillStyle='#b999e522';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#d4b8f3';ctx.setLineDash([7,6]);ctx.strokeRect(0,0,w,h)}ctx.restore();
}
const thumbs=new Map();export function thumbnail(type){if(thumbs.has(type))return thumbs.get(type);const c=document.createElement('canvas');c.width=72;c.height=64;const ctx=c.getContext('2d');ctx.translate(8,8);const dims=type==='platform'?[56,34]:type==='hazard'?[56,28]:type==='flag'?[35,46]:[36,38];paintObject(ctx,{type,x:type==='hazard'?0:8,y:type==='hazard'?15:0,w:dims[0],h:dims[1],color:'#cfe5f6'});const url=c.toDataURL();thumbs.set(type,url);return url}
export function paintBackground(ctx){
 const sky=ctx.createLinearGradient(0,0,0,540);sky.addColorStop(0,'#287bd2');sky.addColorStop(1,'#83c9ec');ctx.fillStyle=sky;ctx.fillRect(-4000,-4000,9000,9000);
 const mountain=(x,y,w,h,c)=>{ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+w*.5,y-h);ctx.lineTo(x+w,y);ctx.closePath();ctx.fill()};mountain(-70,400,500,240,'#4d9cce');mountain(180,450,560,250,'#55a3ce');mountain(520,410,440,210,'#519dcd');mountain(0,380,320,170,'#82bddd');mountain(68,276,110,65,'#cee8ef');mountain(83,280,70,42,'#a6cfe3');
 const cloud=(x,y,s)=>{ctx.fillStyle='#d8f2fa';const blocks=[[0,12,82,18],[12,2,52,20],[24,-8,28,14],[65,16,30,14]];for(const [a,b,w,h]of blocks)ctx.fillRect(x+a*s,y+b*s,w*s,h*s);ctx.fillStyle='#acdae9';ctx.fillRect(x,y+28*s,95*s,5*s)};cloud(65,92,1.1);cloud(430,164,.55);cloud(730,110,1.1);
 for(let i=0;i<14;i++){const x=i*83;ctx.fillStyle=i%2?'#287d83':'#308b88';ctx.beginPath();ctx.arc(x,440-(i%3)*10,100,Math.PI,0);ctx.fill()}for(let i=0;i<9;i++){ctx.fillStyle=i%2?'#246e5d':'#2d8068';ctx.fillRect(i*133,386,13,100);ctx.beginPath();ctx.arc(i*133+7,385,28,0,Math.PI*2);ctx.fill()}
}
